<?php
declare(strict_types=1);requireRole('admin');require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/activity.php';require_once __DIR__.'/../../includes/contact-lens-overview.php';
$activePage='contact-lens-orders';$db=database();$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);function adminLensRedirect(string $m):never{$_SESSION['flash_success']=$m;unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=contact-lens-orders');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired.';$action=(string)($_POST['action']??'');
 if(!$errors)try{
  if($action==='review-request'){$id=filter_input(INPUT_POST,'request_id',FILTER_VALIDATE_INT);$decision=(string)($_POST['decision']??'');$reason=trim((string)($_POST['reason']??''));if(!$id||!in_array($decision,['approved','rejected'],true)||($decision==='rejected'&&$reason===''))throw new RuntimeException('Enter a valid decision and a reason when rejecting.');$q=$db->prepare("UPDATE aid_requests ar JOIN inventory_items i ON i.id=ar.item_id LEFT JOIN item_categories c ON c.id=i.category_id SET ar.status=:status,ar.rejection_reason=:reason,ar.reviewed_by=:admin,ar.reviewed_at=NOW() WHERE ar.id=:id AND ar.status='pending' AND LOWER(CONCAT(COALESCE(i.item_name,''),' ',COALESCE(i.variety,''),' ',COALESCE(c.name,i.category,''))) LIKE '%contact%lens%'");$q->execute(['status'=>$decision,'reason'=>$decision==='rejected'?$reason:null,'admin'=>$_SESSION['user_id'],'id'=>$id]);if($q->rowCount()!==1)throw new RuntimeException('This contact lens request was already reviewed or does not exist.');logActivity('Contact Lens Orders',ucfirst($decision).' contact lens request','CL-'.str_pad((string)$id,3,'0',STR_PAD_LEFT),$decision);adminLensRedirect('Contact lens request '.$decision.'.');}
  if($action==='review'){$id=filter_input(INPUT_POST,'order_id',FILTER_VALIDATE_INT);$decision=(string)($_POST['decision']??'');$reason=trim((string)($_POST['reason']??''));if(!$id||!in_array($decision,['approve','reject'],true)||($decision==='reject'&&$reason===''))throw new RuntimeException('Enter a valid decision and rejection reason when rejecting.');$db->beginTransaction();$q=$db->prepare("SELECT bo.*,COUNT(bi.id) item_count,SUM(bi.quantity) total FROM contact_lens_bulk_orders bo LEFT JOIN contact_lens_bulk_order_items bi ON bi.bulk_order_id=bo.id WHERE bo.id=:id AND bo.status='pending-admin-approval' GROUP BY bo.id FOR UPDATE");$q->execute(['id'=>$id]);$o=$q->fetch();if(!$o)throw new RuntimeException('Order is no longer awaiting Gate 2 review.');if(!(int)$o['item_count']||!(int)$o['total'])throw new RuntimeException('An empty bulk order cannot be approved.');$status=$decision==='approve'?'approved':'rejected';$db->prepare('UPDATE contact_lens_bulk_orders SET status=:status,rejection_reason=:reason,reviewed_by=:user,reviewed_at=NOW() WHERE id=:id')->execute(['status'=>$status,'reason'=>$decision==='reject'?$reason:null,'user'=>$_SESSION['user_id'],'id'=>$id]);$db->commit();logActivity('Contact Lens Bulk Orders','Gate 2 '.($status==='approved'?'approved; send to vendor':'rejected'),$o['order_code'],$status);adminLensRedirect('Bulk order '.$status.'.');}
  if($action==='receive'){$item=filter_input(INPUT_POST,'item_id',FILTER_VALIDATE_INT);$qty=filter_input(INPUT_POST,'quantity',FILTER_VALIDATE_INT);if(!$item||!$qty||$qty<1)throw new RuntimeException('Enter a valid receipt quantity.');$db->beginTransaction();$q=$db->prepare("SELECT bi.*,bo.order_code,bo.status FROM contact_lens_bulk_order_items bi JOIN contact_lens_bulk_orders bo ON bo.id=bi.bulk_order_id WHERE bi.id=:id AND bo.status IN ('approved','partially-received') FOR UPDATE");$q->execute(['id'=>$item]);$r=$q->fetch();if(!$r)throw new RuntimeException('This order is not approved for receipt.');$pending=(int)$r['quantity']-(int)$r['received_quantity'];if($qty>$pending)throw new RuntimeException("Only $pending lens(es) remain pending for this line.");for($i=0;$i<$qty;$i++){$db->prepare("INSERT INTO contact_lens_units(unit_code,bulk_order_id,bulk_order_item_id,power) VALUES('PENDING',:bulk,:item,:power)")->execute(['bulk'=>$r['bulk_order_id'],'item'=>$item,'power'=>$r['power']]);$uid=(int)$db->lastInsertId();$code='CL-'.preg_replace('/^BO-CL-/','',$r['order_code']).'-'.str_pad((string)$uid,4,'0',STR_PAD_LEFT);$db->prepare('UPDATE contact_lens_units SET unit_code=:code WHERE id=:id')->execute(['code'=>$code,'id'=>$uid]);$db->prepare("INSERT INTO contact_lens_unit_history(lens_unit_id,event_type,power,notes,performed_by) VALUES(:unit,'received',:power,:notes,:user)")->execute(['unit'=>$uid,'power'=>$r['power'],'notes'=>'Received against '.$r['order_code'],'user'=>$_SESSION['user_id']]);}$db->prepare('UPDATE contact_lens_bulk_order_items SET received_quantity=received_quantity+:qty WHERE id=:id')->execute(['qty'=>$qty,'id'=>$item]);$q=$db->prepare('SELECT SUM(quantity),SUM(received_quantity) FROM contact_lens_bulk_order_items WHERE bulk_order_id=:id');$q->execute(['id'=>$r['bulk_order_id']]);[$ordered,$received]=$q->fetch(PDO::FETCH_NUM);$status=(int)$received>=(int)$ordered?'fully-received':'partially-received';$db->prepare('UPDATE contact_lens_bulk_orders SET status=:status WHERE id=:id')->execute(['status'=>$status,'id'=>$r['bulk_order_id']]);$db->commit();adminLensRedirect("$qty individual lens unit(s) registered; order is ".str_replace('-',' ',$status).'.');}
  throw new RuntimeException('Invalid workflow action.');
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log($e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to update workflow.';}
}
try{$orders=$db->query("SELECT bo.*,s.company_name,u.full_name creator,COUNT(bi.id) beneficiaries,COALESCE(SUM(bi.quantity),0) total,COALESCE(SUM(bi.received_quantity),0) received FROM contact_lens_bulk_orders bo JOIN suppliers s ON s.id=bo.supplier_id JOIN users u ON u.id=bo.created_by LEFT JOIN contact_lens_bulk_order_items bi ON bi.bulk_order_id=bo.id GROUP BY bo.id ORDER BY FIELD(bo.status,'pending-admin-approval','approved','partially-received','fully-received','draft','rejected','completed'),bo.id DESC")->fetchAll();$items=$db->query("SELECT bi.*,bo.order_code,bo.status order_status,b.full_name,b.nic FROM contact_lens_bulk_order_items bi JOIN contact_lens_bulk_orders bo ON bo.id=bi.bulk_order_id JOIN aid_requests ar ON ar.id=bi.aid_request_id JOIN beneficiaries b ON b.id=ar.beneficiary_id ORDER BY bo.id DESC,bi.id")->fetchAll();$units=$db->query("SELECT lu.*,bo.order_code,b.full_name,b.nic,h.event_type,h.event_at,h.notes FROM contact_lens_units lu JOIN contact_lens_bulk_orders bo ON bo.id=lu.bulk_order_id LEFT JOIN aid_requests ar ON ar.id=lu.aid_request_id LEFT JOIN beneficiaries b ON b.id=ar.beneficiary_id LEFT JOIN contact_lens_unit_history h ON h.id=(SELECT MAX(h2.id) FROM contact_lens_unit_history h2 WHERE h2.lens_unit_id=lu.id) ORDER BY lu.id DESC")->fetchAll();}catch(PDOException $e){error_log($e->getMessage());$orders=$items=$units=[];$errors[]='Bulk workflow unavailable. Run migrations first.';}
?>
